1	//! The layer's one record of the dependency files it could not read, and of what those reads left unfollowed.
2	//!
3	//! A read that fails is unknown, not absent ([`ReadFailed`]). Every decision that depends on one asks this ledger: the
4	//! warnings a layer reports (one per file whose latest read failed), which demands a load follows again, which answers a
5	//! lazy session may memoize, and whether a cold load may write the index. Nothing else holds the fact.
6	//!
7	//! Reads are keyed by path, and marks by the node of the walk that met the failure: a demand, or a declaration it
8	//! claimed. A mark is what a follow found, so a later read of the same file by another walk does not clear it: only
9	//! following that demand again does. Each layer holds only what changed since the layer below; lookups take the newest
10	//! entry in the chain, and a flatten merges the chain's ledgers the same way.
11	
12	use super::*;
13	
14	/// A declaration a load claimed: `(file, name)`.
15	pub(super) type ClaimKey = (PathKey, CompactString);
16	
17	/// A node of the walk a load makes: a demand, or a declaration one claimed, whose references it followed.
18	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
19	pub(super) enum Node {
20	    Demand(DemandKey),
21	    Claim(ClaimKey),
22	}
23	
24	/// The latest read of one dependency file in the chain, kept only once a read of it failed.
25	#[derive(Clone, Debug)]
26	enum Read {
27	    /// Read, or found missing, after an earlier read failed: what it declares is known again.
28	    Done,
29	    /// The file exists but could not be read; the warning reports it.
30	    Failed(Diagnostic),
31	}
32	
33	/// What the latest follow of a node left unread. A node with no mark in the chain reached nothing unread.
34	#[derive(Clone, Debug, Default)]
35	struct Mark {
36	    /// The demand's own walk passed a file it could not read: following it again may answer more.
37	    unread: Option<Demand>,
38	    /// The marked nodes it reached: below it in the same load, or marked by an earlier one.
39	    reaches: Box<[Node]>,
40	}
41	
42	impl Mark {
43	    fn is_clean(&self) -> bool {
44	        self.unread.is_none() && self.reaches.is_empty()
45	    }
46	}
47	
48	/// One layer's entries: what its load read again or could not read, and the marks its follows left.
49	#[derive(Default)]
50	pub(super) struct ReadLedger {
51	    reads: FxHashMap<PathKey, Read>,
52	    marks: FxHashMap<Node, Mark>,
53	}
54	
55	impl ReadLedger {
56	    /// `newer`'s entries over this ledger's, as a flatten merges a chain: the latest entry wins.
57	    fn absorb(&mut self, newer: &ReadLedger) {
58	        self.reads.extend(newer.reads.iter().map(|(path, read)| (path.clone(), read.clone())));
59	        self.marks.extend(newer.marks.iter().map(|(node, mark)| (node.clone(), mark.clone())));
60	    }
61	}
62	
63	/// The demands whose own walk is unread, among `start` and the nodes their marks reach, sorted.
64	fn unread_below<'a>(start: impl IntoIterator<Item = Node>, mark: impl Fn(&Node) -> Option<&'a Mark>) -> Vec<Demand> {
65	    let mut found: Vec<Demand> = Vec::new();
66	    let mut seen: FxHashSet<Node> = FxHashSet::default();
67	    let mut stack: Vec<Node> = start.into_iter().collect();
68	    while let Some(node) = stack.pop() {
69	        let Some(marked) = mark(&node) else { continue };
70	        if !seen.insert(node) {
71	            continue;
72	        }
73	        found.extend(marked.unread.iter().cloned());
74	        stack.extend(marked.reaches.iter().cloned());
75	    }
76	    found.sort();
77	    found.dedup();
78	    found
79	}
80	
81	impl DependencyLayer {
82	    fn has_marks(&self) -> bool {
83	        self.chain().any(|layer| !layer.ledger.marks.is_empty())
84	    }
85	
86	    fn latest_read(&self, file: &str) -> Option<&Read> {
87	        self.chain().find_map(|layer| layer.ledger.reads.get(file))
88	    }
89	
90	    fn mark(&self, node: &Node) -> Option<&Mark> {
91	        self.chain().find_map(|layer| layer.ledger.marks.get(node))
92	    }
93	
94	    /// Whether the latest read of `file` in the chain failed.
95	    fn read_failed(&self, file: &str) -> bool {
96	        matches!(self.latest_read(file), Some(Read::Failed(_)))
97	    }
98	
99	    /// One warning for each file whose latest read in the chain failed, sorted by message.
100	    pub(crate) fn read_warnings(&self) -> Vec<Diagnostic> {
101	        let mut seen: FxHashSet<&PathKey> = FxHashSet::default();
102	        let mut warnings: Vec<Diagnostic> = Vec::new();
103	        for layer in self.chain() {
104	            for (path, read) in &layer.ledger.reads {
105	                if seen.insert(path)
106	                    && let Read::Failed(warning) = read
107	                {
108	                    warnings.push(warning.clone());
109	                }
110	            }
111	        }
112	        warnings.sort_by(|a, b| (&a.message, &a.file).cmp(&(&b.message, &b.file)));
113	        warnings
114	    }
115	
116	    /// Whether the demand's own walk passed a file it could not read, the last time the chain followed it.
117	    pub(super) fn awaits_retry(&self, key: &DemandKey) -> bool {
118	        self.has_marks() && self.mark(&Node::Demand(key.clone())).is_some_and(|mark| mark.unread.is_some())
119	    }
120	
121	    /// Whether a walk of the chain passed a file it could not read and has not been followed since.
122	    pub(crate) fn any_unread(&self) -> bool {
123	        self.chain()
124	            .flat_map(|layer| layer.ledger.marks.iter())
125	            .any(|(node, mark)| mark.unread.is_some() && self.mark(node).is_some_and(|latest| latest.unread.is_some()))
126	    }
127	
128	    /// The demands that `roots` lead to, themselves included, whose walk passed a file that could not be read and has
129	    /// not been followed since, sorted. Following them again is what may answer more; while there are any, what was
130	    /// resolved from `roots` holds for one request only.
131	    pub(crate) fn unread(&self, roots: &[Demand]) -> Vec<Demand> {
132	        if !self.has_marks() {
133	            return Vec::new();
134	        }
135	        unread_below(roots.iter().map(|demand| Node::Demand(demand.key())), |node| self.mark(node))
136	    }
137	}
138	
139	/// The ledger one load builds as it reads and walks; [`LedgerBuilder::finish`] makes the layer's.
140	pub(super) struct LedgerBuilder<'a> {
141	    parent: Option<&'a DependencyLayer>,
142	    /// The chain a flatten took in, merged: consulted as a parent is.
143	    inherited: ReadLedger,
144	    reads: FxDashMap<PathKey, Read>,
145	    /// Each node this load followed, with the nodes it reached: the demands it spawned or met, the declarations it
146	    /// claimed or met claimed.
147	    edges: FxDashMap<Node, Vec<Node>>,
148	    /// The demands whose own walk passed a file it could not read.
149	    unread: FxDashMap<DemandKey, Demand>,
150	    /// The demands followed again because their last walk was unread.
151	    retried: FxDashSet<DemandKey>,
152	}
153	
154	impl<'a> LedgerBuilder<'a> {
155	    pub(super) fn new(parent: Option<&'a DependencyLayer>) -> Self {
156	        LedgerBuilder {
157	            parent,
158	            inherited: ReadLedger::default(),
159	            reads: DashMap::default(),
160	            edges: DashMap::default(),
161	            unread: DashMap::default(),
162	            retried: DashSet::default(),
163	        }
164	    }
165	
166	    /// Take in a layer of the chain a flatten replaces; called oldest first.
167	    pub(super) fn inherit(&mut self, layer: &ReadLedger) {
168	        self.inherited.absorb(layer);
169	    }
170	
171	    fn earlier_mark(&self, node: &Node) -> Option<&Mark> {
172	        self.inherited.marks.get(node).or_else(|| self.parent.and_then(|parent| parent.mark(node)))
173	    }
174	
175	    fn has_earlier_marks(&self) -> bool {
176	        !self.inherited.marks.is_empty() || self.parent.is_some_and(DependencyLayer::has_marks)
177	    }
178	
179	    /// `file` was read, or found missing. Recorded only over an earlier failure, which it ends; within one load a
180	    /// failure stands, since the walk that met it is unread.
181	    pub(super) fn read_done(&self, file: &Utf8Path) {
182	        let earlier = match self.inherited.reads.get(file.as_str()) {
183	            Some(read) => matches!(read, Read::Failed(_)),
184	            None => self.parent.is_some_and(|parent| parent.read_failed(file.as_str())),
185	        };
186	        if earlier {
187	            self.reads.entry(PathKey::from(file)).or_insert(Read::Done);
188	        }
189	    }
190	
191	    pub(super) fn read_failed(&self, file: &Utf8Path, warning: Diagnostic) {
192	        self.reads.insert(PathKey::from(file), Read::Failed(warning));
193	    }
194	
195	    /// Whether this load had a read fail: what it holds is not the whole answer, so it writes no index.
196	    pub(super) fn any_failed(&self) -> bool {
197	        self.reads.iter().any(|entry| matches!(entry.value(), Read::Failed(_)))
198	    }
199	
200	    /// `from` reached `to`, whether it followed `to` itself or found it followed already.
201	    pub(super) fn reached(&self, from: &Node, to: Node) {
202	        self.edges.entry(from.clone()).or_default().push(to);
203	    }
204	
205	    pub(super) fn unread_demand(&self, demand: &Demand) {
206	        self.unread.insert(demand.key(), demand.clone());
207	    }
208	
209	    /// Whether a demand followed before this load is to be followed again (its last walk was unread), and this is the
210	    /// first time this load meets it.
211	    pub(super) fn retries(&self, key: &DemandKey) -> bool {
212	        let unread = self.has_earlier_marks()
213	            && self.earlier_mark(&Node::Demand(key.clone())).is_some_and(|mark| mark.unread.is_some());
214	        unread && self.retried.insert(key.clone())
215	    }
216	
217	    /// The layer's ledger. A node this load followed is marked when it reached an unread walk: its own, one below it
218	    /// in this load, or one an earlier load marked that has not been followed since. A demand followed again that
219	    /// reached none is marked clean, over its earlier mark. A ledger with no parent stands alone, so the chain it took
220	    /// in is merged into it and what is clean is dropped.
221	    pub(super) fn finish(self) -> ReadLedger {
222	        let has_earlier = self.has_earlier_marks();
223	        let LedgerBuilder { parent, inherited, reads, edges, unread, retried } = self;
224	        let earlier = |node: &Node| inherited.marks.get(node).or_else(|| parent.and_then(|parent| parent.mark(node)));
225	        let unread: FxHashMap<Node, Demand> =
226	            unread.into_iter().map(|(key, demand)| (Node::Demand(key), demand)).collect();
227	        let mut marks: FxHashMap<Node, Mark> = FxHashMap::default();
228	        if !unread.is_empty() || has_earlier {
229	            let edges: FxHashMap<Node, Vec<Node>> = edges.into_iter().collect();
230	            let followed = |node: &Node| {
231	                edges.contains_key(node)
232	                    || unread.contains_key(node)
233	                    || matches!(node, Node::Demand(key) if retried.contains(key))
234	            };
235	            // The walks that are unread: this load's own, and the earlier ones this load met without following.
236	            let mut marked: FxHashSet<&Node> = unread.keys().collect();
237	            let mut queue: Vec<&Node> = marked.iter().copied().collect();
238	            let mut reached_by: FxHashMap<&Node, Vec<&Node>> = FxHashMap::default();
239	            for (from, tos) in &edges {
240	                for to in tos {
241	                    reached_by.entry(to).or_default().push(from);
242	                    if !followed(to)
243	                        && !marked.contains(to)
244	                        && earlier(to).is_some()
245	                        && !unread_below([to.clone()], earlier).is_empty()
246	                    {
247	                        marked.insert(to);
248	                        queue.push(to);
249	                    }
250	                }
251	            }
252	            while let Some(node) = queue.pop() {
253	                for &from in reached_by.get(node).into_iter().flatten() {
254	                    if marked.insert(from) {
255	                        queue.push(from);
256	                    }
257	                }
258	            }
259	            for &node in marked.iter().filter(|node| followed(node)) {
260	                let reaches = edges.get(node).into_iter().flatten().filter(|to| marked.contains(to)).cloned().collect();
261	                marks.insert(node.clone(), Mark { unread: unread.get(node).cloned(), reaches });
262	            }
263	            for key in retried {
264	                marks.entry(Node::Demand(key)).or_default();
265	            }
266	        }
267	        let reads: FxHashMap<PathKey, Read> = reads.into_iter().collect();
268	        if parent.is_some() {
269	            return ReadLedger { reads, marks };
270	        }
271	        let mut merged = inherited;
272	        merged.absorb(&ReadLedger { reads, marks });
273	        merged.reads.retain(|_, read| matches!(read, Read::Failed(_)));
274	        merged.marks.retain(|_, mark| !mark.is_clean());
275	        merged
276	    }
277	}
