414	    /// `component` resolved, memoized. `None` when the position is not one of this revision's mappings.
415	    fn lazy_resolved(&self, options: &PipelineOptions, id: &ComponentId, index: usize) -> Option<Arc<Resolved>> {
416	        let lazy = self.lazy.as_ref()?;
417	        if let Some(hit) = lazy.memo.get(id) {
418	            return Some(hit.clone());
419	        }
420	        let mapping = self.global.component_mappings.get(index)?;
421	        // The component's own file almost always reaches its own names; loading them first saves a resolution.
422	        if let Some(seed) = lazy.demands.get(mapping.file_path.as_str()) {
423	            self.grow(options, lazy, seed);
424	        }
425	        let mut asked_for: Vec<dependency_types::Demand> = Vec::new();
426	        loop {
427	            let engine = lazy.engine.load_full();
428	            let (entry, diagnostics, depends_on, evidence, attributes) =
429	                resolve_guarded(&[mapping], &engine.ctx).into_iter().next()?;
430	            // The names the resolution reached that the layer lacks, and the demands below them whose walk passed a
431	            // file that could not be read (the layer's ledger): the next load follows both.
432	            let (missing, unread) = match &engine.layer {
433	                Some(layer) => {
434	                    let roots: Vec<Demand> = depends_on
435	                        .files
436	                        .iter()
437	                        .filter_map(|file| lazy.demands.get(file))
438	                        .flat_map(|demands| demands.iter().cloned())
439	                        .collect();
440	                    let unread = layer.unread(&roots);
441	                    let mut missing = layer.missing(&roots);
442	                    missing.extend(unread.iter().cloned());
443	                    missing.sort();
444	                    missing.dedup();
445	                    (missing, !unread.is_empty())
446	                }
447	                None => (Vec::new(), false),
448	            };
449	            // A resolution against a layer that lacked a name it reached is discarded, and so is its context's memo.
450	            // A load that left the same names missing answered none of them (a demand whose load panicked stays
451	            // unanswered, a file that stays unreadable), so asking again would never end.
452	            if missing.is_empty() || missing == asked_for {
453	                let resolved = Arc::new(Resolved { entry, diagnostics, depends_on, evidence, attributes });
454	                // A walk past a file that could not be read may answer more on the next request, whichever component
455	                // asks: the answer without it is this request's alone.
456	                if unread {
457	                    return Some(resolved);
458	                }
459	                return Some(lazy.memo.entry(id.clone()).or_insert(resolved).clone());
460	            }
461	            self.grow(options, lazy, &missing);
462	            asked_for = missing;
463	        }
464	    }
