466	    /// Once the layer has grown [`WHOLE_DEMAND_AFTER_GROWTHS`] times, load every name the project's files take from a
467	    /// package on a thread of its own, once.
468	    ///
469	    /// Each growth of the layer rebuilds the resolution context, so a session that grows one request at a time pays
470	    /// that rebuild for every new component (Spectrum: 33 rebuilds, about 140 of the 300 ms a project read end to end
471	    /// took). A session that asks about a few components never gets here, and holds only the names they reach; one
472	    /// that reads across the project does, and the later requests find every name loaded. A request that needs a name
473	    /// before the thread has loaded it waits for the same lock and loads it, as it would have anyway.
474	    pub(crate) fn load_whole_demand_in_background(self: &Arc<Self>, options: &PipelineOptions) {
475	        use std::sync::atomic::Ordering::Relaxed;
476	        let Some(lazy) = &self.lazy else { return };
477	        if !options.load_dependencies
478	            || lazy.growths.load(Relaxed) < WHOLE_DEMAND_AFTER_GROWTHS
479	            || lazy.whole_demand_started.swap(true, Relaxed)
480	        {
481	            return;
482	        }
483	        let (revision, options) = (self.clone(), options.clone());
484	        let spawned = std::thread::Builder::new().name("caliper-whole-demand".into()).spawn(move || {
485	            drop(crate::panic_guard::contain_panic("load_whole_demand", || {
486	                let Some(lazy) = &revision.lazy else { return };
487	                let all: Vec<Demand> = lazy.demands.values().flat_map(|demands| demands.iter().cloned()).collect();
488	                revision.grow(&options, lazy, &all);
489	            }));
490	        });
491	        // A thread that cannot start costs the speed-up, never an answer.
492	        if let Ok(handle) = spawned {
493	            *lazy.whole_demand_thread.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(handle);
494	        }
495	    }
496	
497	    /// Wait until the background load [`Self::load_whole_demand_in_background`] started has finished. Without one,
498	    /// returns at once.
499	    pub(crate) fn wait_for_dependency_load(&self) {
500	        let Some(lazy) = &self.lazy else { return };
501	        let handle = lazy.whole_demand_thread.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take();
502	        if let Some(handle) = handle {
503	            drop(handle.join());
504	        }
505	    }
