507	    /// Whether the session's current context holds this revision's own project index, not a copy of it: growing the
508	    /// layer must not clone the project's declarations.
509	    #[cfg(test)]
510	    pub(crate) fn context_shares_project_index(&self) -> Option<bool> {
511	        let lazy = self.lazy.as_ref()?;
512	        Some(lazy.engine.load().ctx.named_types.shares_declarations_with(&self.named_types))
513	    }
514	
515	    /// How many times the dependency layer grew since this revision was built.
516	    #[cfg(test)]
517	    pub(crate) fn layer_growths(&self) -> usize {
518	        self.lazy.as_ref().map_or(0, |lazy| lazy.growths.load(std::sync::atomic::Ordering::Relaxed))
519	    }
520	
521	    /// Load `demands` into the dependency layer unless a concurrent request already did.
522	    fn grow(&self, options: &PipelineOptions, lazy: &Lazy, demands: &[Demand]) {
523	        let _growing = lazy.growing.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
524	        let engine = lazy.engine.load_full();
525	        let Some(layer) = &engine.layer else { return };
526	        let missing = layer.missing(demands);
527	        if missing.is_empty() {
528	            return;
529	        }
530	        let extended = Arc::new(off_pool(|| dependency_types::load(missing, options, Some(layer))));
531	        lazy.growths.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
532	        // Names that were already loaded, or that no package declares, add nothing the resolver reads, so the
533	        // context and its memos stay; only the record of what was asked for moves on.
534	        if extended.resolves_like(layer) {
535	            lazy.engine.store(Arc::new(Engine { layer: Some(extended), ctx: engine.ctx.clone() }));
536	            return;
537	        }
538	        // The new context shares the project's index, import map, resolvers and bare-name tables with the old one;
539	        // rebuilding them for every growth was most of what a session reading across a project spent.
540	        let named_types = Arc::new(self.named_types.with_fallback(extended.named_types.clone()));
541	        let ctx = Arc::new(engine.ctx.over_layer(named_types, Some(extended.clone())));
542	        let next = Engine { layer: Some(extended), ctx };
543	        // A memo that reached a project file whose names the old layer lacked was computed without them, and stays
544	        // behind; the rest hold for the larger layer, so the next component does not rebuild them. While a walk of the
545	        // old layer is unread (its ledger), any memo may hold a declaration read without what lay past the file it
546	        // could not read, a package's own included, and none is kept.
547	        let unread_below = layer.any_unread();
548	        let covered = |file: &str| lazy.demands.get(file).is_none_or(|demands| layer.covers(demands));
549	        next.ctx.inherit_memos(&engine.ctx, |deps, read_in| {
550	            !unread_below
551	                && covered(read_in)
552	                && deps.files.iter().all(|file| covered(std::borrow::Borrow::<str>::borrow(file)))
553	        });
554	        lazy.engine.store(Arc::new(next));
555	    }
556	
557	    /// The keys a batch run publishes the components named `name` under, with each key's position in the group.
558	    /// Only an imported-member alias can be left out (when its package isn't loaded it has nothing to show), so only
559	    /// those are resolved to decide. With `listing`, a session that loads dependencies assumes they are all published
560	    /// instead: deciding would load the package of every alias in the project.
561	    fn group_positions(&self, options: &PipelineOptions, name: &str, listing: bool) -> Vec<(String, usize)> {
562	        let Some(group) = self.lazy.as_ref().and_then(|lazy| lazy.by_name.get(name)) else { return Vec::new() };
563	        let mut keyed: Vec<(String, usize)> = Vec::with_capacity(group.len());
564	        let mut published = 0;
565	        for (position, (id, index)) in group.iter().enumerate() {
566	            let Some(mapping) = self.global.component_mappings.get(*index) else { continue };
567	            let assumed = listing && options.load_dependencies;
568	            if matches!(mapping.rule, DetectionRule::ImportedMemberAlias | DetectionRule::FactoryResult) && !assumed {
569	                let empty = self
570	                    .lazy_resolved(options, id, *index)
571	                    .is_some_and(|resolved| resolved.entry.props.is_empty() && resolved.entry.inheritance.is_empty());
572	                if empty {
573	                    continue;
574	                }
575	            }
576	            published += 1;
577	            // The first occurrence of a name keeps it bare; later ones take their file path, which is unique per file.
578	            let key = if published == 1 { name.to_owned() } else { format!("{name} ({})", mapping.file_path) };
579	            // Two components with one key: the later one is kept, as in the output map.
580	            match keyed.iter_mut().find(|(existing, _)| *existing == key) {
581	                Some(slot) => slot.1 = position,
582	                None => keyed.push((key, position)),
583	            }
584	        }
585	        keyed
586	    }
587	
588	    fn group_keys(&self, options: &PipelineOptions, name: &str, listing: bool) -> Vec<String> {
589	        self.group_positions(options, name, listing).into_iter().map(|(key, _)| key).collect()
590	    }
591	
592	    /// Every key a batch run would publish, sorted. Without `load_dependencies` it resolves the imported-member
593	    /// aliases to decide which are published; with it, it lists them all and never loads a dependency, so the list
594	    /// can include an alias whose package has nothing to show, which `lazy_component` then answers `None` for.
595	    pub(crate) fn lazy_keys(&self, options: &PipelineOptions) -> Vec<String> {
596	        let Some(lazy) = &self.lazy else { return Vec::new() };
597	        let mut keys: Vec<String> = lazy.by_name.keys().flat_map(|name| self.group_keys(options, name, true)).collect();
598	        keys.sort();
599	        keys
600	    }
601	
602	    /// Where each key [`Self::lazy_keys`] lists is declared, sorted by key. Parsing alone answers it; nothing is
603	    /// resolved.
604	    pub(crate) fn lazy_index(&self, options: &PipelineOptions) -> Vec<ComponentLocation> {
605	        let Some(lazy) = &self.lazy else { return Vec::new() };
606	        let mut index: Vec<ComponentLocation> = lazy
607	            .by_name
608	            .iter()
609	            .flat_map(|(name, group)| {
610	                self.group_positions(options, name, true).into_iter().filter_map(|(key, position)| {
611	                    let (id, index) = group.get(position)?;
612	                    let exports = self.global.component_mappings.get(*index)?.exports.clone();
613	                    Some(ComponentLocation { key, file_path: id.file.clone(), display_name: id.name.clone(), exports })
614	                })
615	            })
616	            .collect();
617	        index.sort_by(|a, b| a.key.cmp(&b.key));
618	        index
619	    }
