621	    /// [`Self::lazy_component`] for each of `keys`. The dependency names of every requested component's own file are
622	    /// loaded once up front and the first component is resolved alone, which warms the memos the rest share; resolving
623	    /// them all at once instead makes every thread rebuild the same chains and restart on each layer growth.
624	    pub(crate) fn lazy_components(&self, options: &PipelineOptions, keys: &[String]) -> Vec<Option<ComponentAnswer>> {
625	        use rayon::prelude::*;
626	        let Some(lazy) = &self.lazy else { return vec![None; keys.len()] };
627	        let mut seed: Vec<Demand> = Vec::new();
628	        let mut seeded: FxHashSet<&Utf8Path> = FxHashSet::default();
629	        for key in keys {
630	            let Some((id, index)) = self.lazy_target(options, key) else { continue };
631	            let Some(mapping) = self.global.component_mappings.get(index) else { continue };
632	            if let Some(demands) = lazy.demands.get(mapping.file_path.as_str()).filter(|_| seeded.insert(&id.file)) {
633	                seed.extend(demands.iter().cloned());
634	            }
635	        }
636	        if !seed.is_empty() {
637	            self.grow(options, lazy, &seed);
638	        }
639	        let mut answers: Vec<Option<ComponentAnswer>> = vec![None; keys.len()];
640	        let Some((first, rest)) = keys.split_first() else { return answers };
641	        let (head, tail) = answers.split_at_mut(1);
642	        if let Some(slot) = head.first_mut() {
643	            *slot = self.lazy_component(options, first);
644	        }
645	        tail.par_iter_mut().zip(rest.par_iter()).for_each(|(slot, key)| *slot = self.lazy_component(options, key));
646	        answers
647	    }
648	
649	    /// The key a batch run publishes the component `name` declared in `file` under. `None` when `file` declares no
650	    /// such component, or a batch run would leave it out.
651	    pub(crate) fn lazy_key_in(&self, options: &PipelineOptions, file: &Utf8Path, name: &str) -> Option<String> {
652	        let group = self.lazy.as_ref()?.by_name.get(name)?;
653	        self.group_positions(options, name, false)
654	            .into_iter()
655	            .rev()
656	            .find(|(_, position)| group.get(*position).is_some_and(|(id, _)| id.file == file))
657	            .map(|(key, _)| key)
658	    }
