660	    /// The component a batch run publishes under `key`, and its place in the revision: the id and the position of
661	    /// its mapping. `None` for a key with no component.
662	    fn lazy_target(&self, options: &PipelineOptions, key: &str) -> Option<(&ComponentId, usize)> {
663	        let lazy = self.lazy.as_ref()?;
664	        // `key` is a bare name, or `Name (file)`; a name may itself contain " (" only in a path, never a component.
665	        let names = std::iter::once(key).chain(key.match_indices(" (").map(|(at, _)| &key[..at]));
666	        let (name, position) = names.into_iter().find_map(|name| {
667	            let position =
668	                self.group_positions(options, name, false).into_iter().find(|(candidate, _)| candidate == key)?.1;
669	            Some((name, position))
670	        })?;
671	        let (id, index) = lazy.by_name.get(name)?.get(position)?;
