11	fn project(files: &[(&str, &str)]) -> (tempfile::TempDir, Utf8PathBuf) {
12	    let tmp = tempfile::TempDir::new().unwrap();
13	    let root = Utf8PathBuf::from_path_buf(tmp.path().canonicalize().unwrap()).unwrap();
14	    for (path, body) in files {
15	        write(&root, path, body);
16	    }
17	    (tmp, root)
18	}
