53	fn a_file_that_stays_unreadable_is_reported_once_however_often_the_layer_grows() {
54	    let (_tmp, root) = project(SOLO);
55	    let props = root.join("node_modules/solo-kit/props.d.ts");
56	    std::fs::write(&props, UNREADABLE).unwrap();
