172	fn a_prop_a_package_file_inherits_from_an_unreadable_file_appears_once_the_file_reads() {
173	    let (_tmp, root) = project(NESTED);
174	    let base = root.join("node_modules/nest-kit/base.d.ts");
175	    let text = std::fs::read_to_string(&base).unwrap();
