178	    drop(session.initialize());
179	    std::fs::write(&base, UNREADABLE).unwrap();
180	    let card = session.component("Card");
181	    assert_eq!(names(&card), ["own", "title"], "answered from what was read");
182	    assert_eq!(warned(&card), [Some(base.to_string())]);
