244	/// Each component, what it imports, and the package files its walk reads when every file is readable: its demands'
245	/// export walks, the declarations they extend, and the augmentation search of the module its file imports.
246	const MODEL_COMPONENTS: &[(&str, &str, &[&str])] = &[
247	    ("A", "AProps", &["index", "a", "stub", "b", "nest"]),
248	    ("B", "BProps", &["index", "a", "stub", "b", "nest"]),
249	    ("N", "Nest", &["index", "a", "stub", "b", "nest", "deep", "leaf"]),
250	    ("All", "AProps, BProps, Nest", &["index", "a", "stub", "b", "nest", "deep", "leaf"]),
251	];
