253	fn model_source(name: &str, imports: &str, edit: usize) -> String {
254	    let own = name.to_lowercase();
255	    format!(
256	        "import type {{ {imports} }} from 'mk';\ninterface {name}Own extends {imports} {{ own_{own}: string }}\n\
257	         export function {name}(props: {name}Own) {{ return null; }}\n// edit {edit}\n"
258	    )
259	}
