261	fn model_project() -> (tempfile::TempDir, Utf8PathBuf) {
262	    let (tmp, root) = project(MODEL_PACKAGE);
263	    for (name, imports, _) in MODEL_COMPONENTS {
264	        write(&root, &format!("src/{name}.tsx"), &model_source(name, imports, 0));
265	    }
266	    (tmp, root)
267	}
