269	/// Exactly `unreadable` of the package's declaration files unreadable, the rest as written.
270	fn set_unreadable(root: &Utf8Path, unreadable: &std::collections::BTreeSet<&str>) {
271	    for (path, body) in MODEL_PACKAGE {
272	        let Some(name) = path.strip_prefix("node_modules/mk/").and_then(|name| name.strip_suffix(".d.ts")) else {
273	            continue;
274	        };
275	        match unreadable.contains(name) {
276	            true => std::fs::write(root.join(path), UNREADABLE).unwrap(),
277	            false => std::fs::write(root.join(path), body).unwrap(),
278	        }
279	    }
280	}
