282	/// The package files an answer's read warnings name, by their short name, one entry per warning.
283	fn warned_names(root: &Utf8Path, answer: &ComponentAnswer) -> Vec<String> {
284	    let prefix = format!("{root}/node_modules/mk/");
285	    let mut names: Vec<String> = answer
286	        .diagnostics
287	        .iter()
288	        .filter(|diagnostic| diagnostic.code == DiagnosticCode::IoError)
289	        .map(|diagnostic| {
290	            let file = diagnostic.file.as_deref().unwrap_or_default();
291	            file.trim_start_matches(&prefix).trim_end_matches(".d.ts").to_owned()
292	        })
