305	/// A model-based test of what a lazy session holds while package files go unreadable and readable again: a seeded
306	/// sequence of files made unreadable (bytes that are not UTF-8) or readable, requests and project edits. After every
307	/// request:
308	///
309	/// 1. the answer equals a fresh session's (cache off) with exactly the files the session reports unreadable made
310	///    unreadable: the cold answer when it reports none, the cold answer minus exactly what those files held otherwise;
311	/// 2. each file is reported once, and a request made while every file reads reports none of the files its own walk
312	///    reads (it read them again);
313	/// 3. once every file reads, every component equals the cold answer, with no warning, in this session and in the next
314	///    one over the same cache: nothing from a degraded answer was memoized or persisted.
315	///
316	/// A failure prints the seed and the steps so far.
317	#[test]
318	fn a_session_over_files_that_go_unreadable_answers_as_a_fresh_one_over_what_it_could_read() {
319	    let names: Vec<&str> = MODEL_PACKAGE
320	        .iter()
321	        .filter_map(|(path, _)| path.strip_prefix("node_modules/mk/")?.strip_suffix(".d.ts"))
322	        .collect();
323	    let (_oracle_tmp, oracle_root) = model_project();
324	    let mut oracle_answers: FxHashMap<(String, Vec<String>), String> = FxHashMap::default();
325	    let mut oracle = |component: &str, unreadable: &[String]| -> String {
326	        let key = (component.to_owned(), unreadable.to_vec());
327	        oracle_answers
328	            .entry(key)
329	            .or_insert_with(|| {
330	                set_unreadable(&oracle_root, &unreadable.iter().map(String::as_str).collect());
331	                let fresh = WatchSession::lazy(PipelineOptions { use_cache: false, ..options(&oracle_root) });
332	                drop(fresh.initialize());
333	                comparable(&oracle_root, &fresh.component(component).unwrap())
334	            })
335	            .clone()
336	    };
337	    for seed in [1_u64, 2, 3, 5, 8, 13, 21, 34] {
338	        let (_tmp, root) = model_project();
339	        let mut state = seed.wrapping_mul(0x9e37_79b9_7f4a_7c15) | 1;
340	        let mut next = |bound: usize| -> usize {
341	            state ^= state << 13;
342	            state ^= state >> 7;
343	            state ^= state << 17;
344	            (state % bound as u64) as usize
345	        };
346	        let mut unreadable: std::collections::BTreeSet<&str> = std::collections::BTreeSet::new();
347	        let mut log: Vec<String> = Vec::new();
348	        let session = WatchSession::lazy(options(&root));
349	        if next(2) == 0 {
350	            unreadable.insert(names[next(names.len())]);
351	            set_unreadable(&root, &unreadable);
352	            log.push(format!("unreadable before start: {unreadable:?}"));
353	        }
354	        drop(session.initialize());
355	        for step in 0..40 {
356	            let context = |log: &[String]| format!("seed {seed}, step {step}:\n{}", log.join("\n"));
357	            match next(4) {
358	                0 => {
359	                    let name = names[next(names.len())];
360	                    if !unreadable.remove(name) {
361	                        unreadable.insert(name);
362	                    }
363	                    set_unreadable(&root, &unreadable);
364	                    log.push(format!("unreadable: {unreadable:?}"));
365	                }
366	                1 => {
367	                    let (name, imports, _) = MODEL_COMPONENTS[next(MODEL_COMPONENTS.len())];
368	                    let file = root.join(format!("src/{name}.tsx"));
369	                    std::fs::write(&file, model_source(name, imports, step + 1)).unwrap();
370	                    drop(session.update_file(&file));
371	                    log.push(format!("edit {name}"));
372	                }
373	                _ => {
374	                    let (name, _, reads) = MODEL_COMPONENTS[next(MODEL_COMPONENTS.len())];
375	                    let all_read = unreadable.is_empty();
376	                    let answer = session.component(name).unwrap();
377	                    session.wait_for_dependency_load();
378	                    log.push(format!("request {name}"));
379	                    let warned = warned_names(&root, &answer);
380	                    let mut once = warned.clone();
381	                    once.dedup();
382	                    assert_eq!(warned, once, "each file is reported once: {}", context(&log));
383	                    assert_eq!(comparable(&root, &answer), oracle(name, &warned), "{}", context(&log));
384	                    if all_read {
385	                        let reread: Vec<&String> =
386	                            warned.iter().filter(|file| reads.contains(&file.as_str())).collect();
387	                        assert_eq!(reread, Vec::<&String>::new(), "read again: {}", context(&log));
388	                    }
389	                }
390	            }
391	        }
392	        unreadable.clear();
393	        set_unreadable(&root, &unreadable);
394	        for (name, _, _) in MODEL_COMPONENTS {
395	            drop(session.component(name));
396	            session.wait_for_dependency_load();
397	        }
398	        let next_session = WatchSession::lazy(options(&root));
399	        drop(next_session.initialize());
400	        for (name, _, _) in MODEL_COMPONENTS {
401	            let cold = oracle(name, &[]);
402	            let context = format!("seed {seed}, all readable, {name}:\n{}", log.join("\n"));
403	            let answer = session.component(name).unwrap();
404	            assert_eq!(warned_names(&root, &answer), Vec::<String>::new(), "{context}");
